insert into public.sm_pages(id,slug,title_ar,title_en,body_ar,body_en,image,published) values ('20000000-0000-4000-8000-000000000001','hero','كل ما يحتاجه مشروعك الترفيهي','Everything your play project needs','ألعاب حركية، تجهيزات وقطع غيار في مكان واحد.','Play equipment, installations and spare parts in one place.','assets/hero.png',true) on conflict(id) do nothing;
insert into public.sm_pages(id,slug,title_ar,title_en,body_ar,body_en,image,published) values ('20000000-0000-4000-8000-000000000002','about','من نحن','About us','نحن مصنع متخصص في تصميم وتجهيز الألعاب الحركية للأطفال. نخدم رواد الأعمال والمدارس والحضانات والمراكز التجارية ومراكز الترفيه في مختلف مناطق المملكة. نبدأ بدراسة الموقع وتصميم ثلاثي الأبعاد ثم التصنيع والتركيب والتسليم والمتابعة.','We design and manufacture active play equipment for children, serving entrepreneurs, schools, nurseries, malls and entertainment centres across Saudi Arabia. Our process covers site planning, 3D design, manufacturing, installation and after-sales support.','',true) on conflict(id) do nothing;
insert into public.sm_pages(id,slug,title_ar,title_en,body_ar,body_en,image,published) values ('20000000-0000-4000-8000-000000000003','services','ماذا نقدم؟','Our services','تصميم الصالات الداخلية • سوفت بلاي • تسلق وقفز وزحاليق • ترامبولين • ملاعب كرة قدم للأطفال • ألعاب تعليمية وذكاء • تصميم حسب المساحة والميزانية.','Indoor play areas • Soft play • Climbing, jumping and slides • Trampolines • Children’s football areas • Educational activities • Layouts tailored to your space and budget.','',true) on conflict(id) do nothing;
insert into public.sm_pages(id,slug,title_ar,title_en,body_ar,body_en,image,published) values ('20000000-0000-4000-8000-000000000004','terms','شروط الطلب','Order terms','الطلب المرسل هو طلب عرض سعر للمراجعة. يتم تأكيد التوفر والشحن والمعالجة الضريبية والإجمالي النهائي قبل الدفع. لا يُطلب تحويل مالي قبل استلام عرض السعر المعتمد.','Your submission is a quotation request. Availability, shipping, tax treatment and the final total are confirmed before payment. Do not transfer funds before receiving an approved quotation.','',true) on conflict(id) do nothing;
insert into public.sm_settings(id,brand_ar,brand_en,whatsapp,instagram,payment_ar,payment_en,shipping_ar,shipping_en) values ('global','صُنّاع البسمة للترفيه','Smile Makers','','https://www.instagram.com/fun_maker2010','نرسل بيانات التحويل وعرض السعر بعد مراجعة الطلب.','Bank details and a quotation are provided after reviewing your request.','تُحدد تكلفة الشحن ومدة التوصيل بعد مراجعة موقع المشروع والمنتجات.','Shipping cost and delivery time are confirmed after reviewing your location and items.') on conflict(id) do nothing;
